            ln = ln + len(words[j]) + (1 if j>i else 0)
            tot = ln + indents(li)
            isLast = (j+1==n)
            if tot> W and j>i:
                break
            slack = W-tot
            if isLast and not include_last:
                cost=0
            else:
                cost = abs(slack)**power if slack>=0 else INF
            sub=f(j+1, li+1)
            c = cost + sub[0]
            if c < res[0]:
                res=(c,(ln,)+sub[1])
            j+=1
        return res
